import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent defections and our recent behavior.
    opp_def = 0
    opp_c = 0
    my_def = 0
    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_def += 1
        else:
            opp_c += 1
        if me == 'D':
            my_def += 1

    last_me, last_op = history[-1]

    # Near the end of a 100-round match, defect more often.
    remaining = 100 - n

    # If opponent has defected very rarely, cooperate as a base.
    if opp_def == 0:
        # Exploit at the very end.
        if remaining <= 1:
            return 'D'
        return 'C'

    # Strong retaliation if opponent has defected recently.
    recent_d = 0
    look = min(n, 8)
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_d += 1

    # Endgame exploitation: defect in the last few rounds.
    if remaining <= 2:
        return 'D'

    # If opponent is heavily defecting, punish but sometimes test cooperation.
    if recent_d >= 4:
        return 'D'

    if recent_d >= 2:
        # Mostly punish, occasionally cooperate to avoid lock-in.
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # If opponent has shown persistent defection overall, be cautious.
    if opp_def * 3 > n:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Forgiving tit-for-tat-ish behavior with some random noise resistance.
    if last_op == 'D':
        # Retaliate, but sometimes forgive to restart cooperation.
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Cooperate by default in midgame.
    return 'C'
